}

const montoUsd = Number(match[1]);
const tasa = Number($json.promedio ?? $json.venta ?? $json.compra ?? $json.price);

if (!Number.isFinite(montoUsd) || !Number.isFinite(tasa)) {
  return { json: { Content: 'No pude calcular la conversión.' } };
}

const totalBs = montoUsd * tasa;

return {
  json: {
    Content: `$${montoUsd.toLocaleString('es-VE', {
      minimumFractionDigits: 2,
