     cleanText = cleanText.replace(/"/g, '');

    // 4. Recortar espacios en blanco al inicio y al final
    cleanText = cleanText.trim();

     // Asigna el texto limpio a una nueva propiedad
    item.json.final_text = cleanText;
  }
}

return items;

